//! Differential corpus gate (§4.8): the Rust validator must agree with the
//! verdicts of the real prosemirror-model on every corpus case. The corpus
//! is generated by `schema-tests/generator` (TypeScript, real
//! prosemirror-model) and committed; CI regenerates it and requires a
//! byte-identical result.

use std::path::Path;

use serde_json::Value;

fn corpus_path() -> std::path::PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("..")
        .join("..")
        .join("schema-tests")
        .join("fixtures")
        .join("corpus.jsonl")
}

#[test]
fn rust_validator_agrees_with_prosemirror_on_the_whole_corpus() {
    let raw = std::fs::read_to_string(corpus_path()).expect("corpus.jsonl is committed");
    let artifact = insum_core::schema::resolve(
        None,
        Path::new("/nonexistent-for-fallback"),
        &insum_core::Limits::defaults(),
    )
    .expect("bundled fallback resolves");
    assert_eq!(
        artifact.source,
        insum_core::schema::SchemaSource::BundledFallback
    );
    let pm = insum_core::pmschema::PmSchema::build(&artifact.artifact).expect("artifact compiles");
    let limits = insum_core::Limits::defaults();

    let mut lines = raw.lines();
    // the first line is provenance (P-01): which artifact snapshot and
    // reference library produced these verdicts — the gate refuses a
    // corpus whose provenance does not match the artifact it replays with
    let provenance: Value = serde_json::from_str(
        lines
            .next()
            .expect("corpus.jsonl starts with a provenance record"),
    )
    .expect("provenance line is JSON");
    assert_eq!(
        provenance["record"], "provenance",
        "corpus.jsonl must start with a provenance record"
    );
    let declared_hash = provenance["schema_hash"]
        .as_str()
        .expect("provenance carries schema_hash");
    assert_eq!(
        declared_hash, artifact.artifact.schema_hash,
        "corpus provenance does not match the artifact this gate replays with"
    );
    assert!(
        provenance["prosemirror_model"].is_string() && provenance["seed"].is_i64(),
        "provenance names the reference library and the seed"
    );

    // the synthetic supplement (T-09/P-04) carries its whole artifact:
    // cases tagged schema:"synthetic" are replayed against a second
    // validator built from it
    let pm_synthetic = if provenance["synthetic_artifact"].is_object() {
        Some(
            insum_core::pmschema::PmSchema::build(
                &insum_core::schema::SchemaArtifact::parse(
                    provenance["synthetic_artifact"].clone(),
                )
                .expect("the embedded synthetic artifact parses"),
            )
            .expect("the embedded synthetic artifact compiles"),
        )
    } else {
        None
    };

    let mut total = 0usize;
    let mut mismatches: Vec<String> = Vec::new();
    for line in lines {
        if line.trim().is_empty() {
            continue;
        }
        let case: Value = serde_json::from_str(line).expect("corpus line is JSON");
        let id = case["id"].as_str().unwrap_or("<no id>").to_owned();
        let category = case["category"]
            .as_str()
            .unwrap_or("<no category>")
            .to_owned();
        let expected_valid = case["expected"].as_str() == Some("valid");
        let doc = &case["doc"];

        let case_schema = case["schema"].as_str().unwrap_or("main");
        let replay_schema: Option<&insum_core::pmschema::PmSchema> = match case_schema {
            "main" => Some(&pm),
            "synthetic" => pm_synthetic.as_ref(),
            other => panic!("unknown schema tag {other:?} in the corpus"),
        };

        let validation =
            insum_core::validate_note_doc_with_schema(doc, false, &limits, replay_schema)
                .expect("corpus documents stay within read limits");
        let actual_valid = validation.valid();
        total += 1;

        if actual_valid != expected_valid {
            mismatches.push(format!(
                "case {id} ({category}): expected {expected}, rust says {actual}\n  doc: {}\n  rust errors: {:?}\n  rust warnings: {:?}",
                case["doc"],
                validation
                    .errors
                    .iter()
                    .map(|e| format!("{}: {}", e.code, e.message))
                    .collect::<Vec<_>>(),
                validation
                    .warnings
                    .iter()
                    .map(|w| format!("{}: {}", w.code, w.message))
                    .collect::<Vec<_>>(),
                expected = if expected_valid { "valid" } else { "invalid" },
                actual = if actual_valid { "valid" } else { "invalid" },
            ));
        }
    }

    assert!(
        total >= 100,
        "the corpus shrunk unexpectedly: {total} cases (generator broken?)"
    );
    // the parent-mark-set rule must keep real negative coverage (P-02):
    // a patch removing the child-marks check would flip these cases into
    // divergences above
    assert!(
        raw.lines().any(|line| {
            serde_json::from_str::<Value>(line)
                .ok()
                .is_some_and(|case| {
                    case["category"]
                        .as_str()
                        .is_some_and(|c| c.starts_with("invalid-mark-not-allowed-in-code-row"))
                })
        }),
        "the corpus lost its parent-mark-set negative coverage"
    );
    assert!(
        mismatches.is_empty(),
        "unexplained divergences between rust and prosemirror-model ({}):\n\n{}",
        mismatches.len(),
        mismatches.join("\n\n")
    );
}
